#!/bin/sh
# Checks the generated grammars against the C compiler's view of the same
# parser.c files (cgo). Usage: ./run.sh [-text N] [grammar ...]
#
# The check must not depend on the runtime or on the hand-written scanners, so
# it builds against a copy: api.go as it is, mock.go.txt as the Lexer, and
# each grammar's generated files.
set -e
here=$(cd "$(dirname "$0")" && pwd)
root=$(cd "$here/../../.." && pwd)
fake=$root/scratch/gramcheck/fake
rm -rf "$fake"
mkdir -p "$fake/grammars"
printf 'module github.com/dobbo-ca/gositter\n\ngo 1.25\n' > "$fake/go.mod"
cp "$root/api.go" "$fake/api.go"
cp "$here/mock.go.txt" "$fake/mock.go"

reg=$here/zz_langs.go
{
  echo "// Code generated by run.sh. DO NOT EDIT."
  echo
  echo "package main"
  echo
  echo "import ("
  echo "	\"github.com/dobbo-ca/gositter\""
  for d in "$root"/grammars/*/; do
    n=$(basename "$d")
    [ -f "$d/tables.go" ] || continue
    mkdir -p "$fake/grammars/$n"
    cp "$d/tables.go" "$d/lex.go" "$d/language.go" "$fake/grammars/$n/"
    if grep -q 'New: *newScanner' "$d/language.go"; then
      printf 'package %s\n\nimport "github.com/dobbo-ca/gositter"\n\nfunc newScanner() gositter.ExternalScanner { return nil }\n' "$n" > "$fake/grammars/$n/zz_scanner.go"
    fi
    echo "	g_$n \"github.com/dobbo-ca/gositter/grammars/$n\""
  done
  echo ")"
  echo
  echo "var goLangs = map[string]func() *gositter.Language{"
  for d in "$fake"/grammars/*/; do
    n=$(basename "$d")
    echo "	\"$n\": g_$n.Language,"
  done
  echo "}"
} > "$reg"

# MUTATE is a shell snippet run in the copy, to see the check fail:
#   MUTATE="sed -i '' '0,/<= lookahead/s//< lookahead/' grammars/json/lex.go" ./run.sh json
[ -z "$MUTATE" ] || (cd "$fake" && eval "$MUTATE")

cd "$here"
trap 'rm -f "$reg"' EXIT
GOFLAGS=-mod=mod go build -o "$root/scratch/gramcheck/check" .
rm -f "$reg"
"$root/scratch/gramcheck/check" -tree "$fake/grammars" "$@"
